package org.synqoria.scheduling;import java.util.*;
public class AppointmentIdempotencyLedgerTest{public static void main(String[]a){int n=0;var s=new AppointmentIdempotencyLedger();var t=UUID.randomUUID();var f=UUID.randomUUID();var actor=UUID.randomUUID();check(s.checkAndRecord(t,f,actor,"key_123456","a".repeat(64))==AppointmentIdempotencyLedger.Outcome.FIRST_SEEN);n++;check(s.checkAndRecord(t,f,actor,"key_123456","a".repeat(64))==AppointmentIdempotencyLedger.Outcome.REPLAY_SAME_COMMAND);n++;check(s.checkAndRecord(t,f,actor,"key_123456","b".repeat(64))==AppointmentIdempotencyLedger.Outcome.CONFLICT_DIFFERENT_COMMAND);n++;check(s.checkAndRecord(t,f,UUID.randomUUID(),"key_123456","b".repeat(64))==AppointmentIdempotencyLedger.Outcome.FIRST_SEEN);n++;check(s.checkAndRecord(UUID.randomUUID(),f,actor,"key_123456","b".repeat(64))==AppointmentIdempotencyLedger.Outcome.FIRST_SEEN);n++;check(s.size()==3);n++;try{s.checkAndRecord(t,f,actor,"bad","a".repeat(64));throw new AssertionError();}catch(IllegalArgumentException expected){n++;}try{s.checkAndRecord(t,f,actor,"key_123456","g".repeat(64));throw new AssertionError();}catch(IllegalArgumentException expected){n++;}System.out.println("PASS "+n+" idempotency assertions");}static void check(boolean b){if(!b)throw new AssertionError();}}
